 final int BG=0xff0b1020,CARD=0xff19233b,INK=0xfff4f6ff,MUTED=0xffa4afc8,ACCENT=0xffa6f5d2; LinearLayout root,body,nav; TextView de,uk,lesson,count,status,play,disc; SeekBar progress; boolean drawing=false,seek=false; int tab=0; String filter=""; boolean importing=false; Handler h=new Handler();
