 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}int l(){return Store.prefs(this).getInt("lesson",0);}int p(){return Store.prefs(this).getInt("phrase",0);}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);show(0);}
 protected void onResume(){super.onResume();h.removeCallbacks(tick);h.post(tick);}protected void onPause(){h.removeCallbacks(tick);super.onPause();}
