 void show(int t){tab=t;root=column();root.setBackgroundColor(BG);root.setPadding(dp(18),dp(12),dp(18),dp(10));setContentView(root);LinearLayout header=row();TextView brand=label("Language Pro",25,INK,true);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView tag=label("3.1  •  AUDIO",12,ACCENT,true);header.addView(tag);add(root,header,0);ScrollView sc=new ScrollView(this);sc.setFillViewport(false);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));body=column();body.setPadding(0,dp(16),0,dp(12));sc.addView(body);nav=row();String[] a={"♫\nПлеєр","▤\nУроки","◉\nПереклад","⚙\nОпції"};for(int i=0;i<a.length;i++){final int k=i;TextView v=btn(a[i],12,t==i,()->{if(k==2){cmd("PAUSE");startActivity(new Intent(this,VoiceActivity.class));}else show(k);});weight(nav,v);}add(root,nav,6);if(t==0)player();else if(t==1)library();else settings();}
 void player(){add(body,label("ТВІЙ АУДІОКУРС",12,ACCENT,true),0);lesson=label("",24,INK,true);add(body,lesson,6);LinearLayout hero=column();hero.setGravity(Gravity.CENTER);hero.setPadding(dp(20),dp(22),dp(20),dp(22));GradientDrawable grad=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff33476a,0xff19263b,0xff154139});grad.setCornerRadius(dp(28));hero.setBackground(grad);disc=label("",14,ACCENT,true);disc.setGravity(Gravity.CENTER);add(hero,disc,0);TextView wave=label("▂ ▃ ▆ ▂ ▅ ▇ ▄ ▂ ▅ ▃ ▂",28,ACCENT,true);wave.setGravity(Gravity.CENTER);add(hero,wave,12);de=label("",30,INK,true);de.setGravity(Gravity.CENTER);add(hero,de,16);uk=label("",19,0xffd5e0f6,false);uk.setGravity(Gravity.CENTER);add(hero,uk,13);status=label("",12,ACCENT,true);status.setGravity(Gravity.CENTER);add(hero,status,18);add(body,hero,18);count=label("",13,MUTED,true);add(body,count,16);progress=new SeekBar(this);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(ACCENT));progress.setThumbTintList(android.content.res.ColorStateList.valueOf(ACCENT));add(body,progress,0);progress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){seek=true;}public void onStopTrackingTouch(SeekBar s){seek=false;Store.prefs(MainActivity.this).edit().putInt("phrase",s.getProgress()).apply();cmd("RESET");update();}public void onProgressChanged(SeekBar s,int v,boolean user){if(user)count.setText("Фраза "+(v+1)+" / "+(s.getMax()+1));}});LinearLayout controls=row();weight(controls,btn("|◀",24,false,()->cmd("PREV")));play=btn("▶",32,true,()->cmd("TOGGLE"));weight(controls,play);weight(controls,btn("▶|",24,false,()->cmd("NEXT")));add(body,controls,10);LinearLayout extra=row();weight(extra,btn("↻ Повтор",14,false,()->{boolean b=!Store.prefs(this).getBoolean("repeat",false);Store.prefs(this).edit().putBoolean("repeat",b).apply();Toast.makeText(this,b?"Повтор увімкнено":"Повтор вимкнено",0).show();}));weight(extra,btn("▤ Усі фрази",14,false,()->phrases(l())));add(body,extra,12);add(body,btn("◉ Голосовий перекладач",16,false,()->{cmd("PAUSE");startActivity(new Intent(this,VoiceActivity.class));}),14);add(body,label("Порада: можна заблокувати екран і керувати відтворенням зі сповіщення.",13,MUTED,false),18);update();}
 void update(){if(de==null)return;int n=Store.phrases(this,l()).length();lesson.setText(Store.title(this,l()));disc.setText(Store.name(Store.language(this,l()))+" / Українська");de.setText(Store.phrase(this,l(),p(),"de"));uk.setText(Store.phrase(this,l(),p(),"uk"));count.setText("Фраза "+(n==0?0:p()+1)+" з "+n);progress.setMax(Math.max(0,n-1));progress.setProgress(Math.min(p(),progress.getMax()));status.setText(PlayerService.status);play.setText(PlayerService.playing?"Ⅱ":"▶");}
 void select(int a,int b){filter=Store.language(this,a);Store.prefs(this).edit().putInt("lesson",a).putInt("phrase",b).apply();cmd("RESET");show(0);}
 void phrases(int a){JSONArray arr=Store.phrases(this,a);String[] items=new String[arr.length()];for(int i=0;i<items.length;i++)items[i]=Store.phrase(this,a,i,"de")+"\n"+Store.phrase(this,a,i,"uk");new AlertDialog.Builder(this).setTitle(Store.title(this,a)).setItems(items,(d,k)->select(a,k)).setNegativeButton("Закрити",null).show();}
 void library(){add(body,label("Бібліотека уроків",27,INK,true),0);JSONArray all=Store.lessons(this);add(body,label(all.length()+" уроків • навчання у власному темпі",14,MUTED,false),7);add(body,btn("＋ Додати урок з файлу",16,true,()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,15);}),18);add(body,btn("✎ Створити урок українською",16,false,()->importDialog("Новий урок","")),10);add(body,btn(filter.isEmpty()?"Усі мови":Store.name(filter),15,false,()->{String[] names=new String[Store.NAMES.length+1];names[0]="Усі мови";System.arraycopy(Store.NAMES,0,names,1,Store.NAMES.length);new AlertDialog.Builder(this).setTitle("Мова бібліотеки").setItems(names,(d,j)->{filter=j==0?"":Store.LANGS[j-1];show(1);}).show();}),10);for(int i=0;i<all.length();i++){if(!filter.isEmpty()&&!filter.equals(Store.language(this,i)))continue;final int k=i;LinearLayout item=row();item.setPadding(dp(13),dp(12),dp(10),dp(12));item.setBackground(bg(CARD,20));TextView ico=label("♫",22,ACCENT,true);item.addView(ico,new LinearLayout.LayoutParams(dp(42),-2));LinearLayout txt=column();add(txt,label(Store.title(this,i),16,INK,true),0);add(txt,label(Store.name(Store.language(this,i))+" • "+Store.phrases(this,i).length()+" фраз",12,MUTED,false),5);item.addView(txt,new LinearLayout.LayoutParams(0,-2,1));TextView more=btn("⋮",22,false,()->new AlertDialog.Builder(this).setTitle(Store.title(this,k)).setItems(new String[]{"Показати фрази","Видалити урок"},(d,j)->{if(j==0)phrases(k);else new AlertDialog.Builder(this).setMessage("Видалити цей урок?").setPositiveButton("Видалити",(dd,jj)->{cmd("STOP");Store.delete(this,k);show(1);}).setNegativeButton("Скасувати",null).show();}).show());item.addView(more);item.setOnClickListener(v->select(k,0));add(body,item,10);}}
 void settings(){add(body,label("Налаштування",27,INK,true),0);add(body,label("Відтворення",15,ACCENT,true),22);slider("Пауза між фразами",Store.prefs(this).getInt("pause",4)-1,9,1," с",x->Store.prefs(this).edit().putInt("pause",x+1).apply());slider("Швидкість голосу",Math.round(Store.prefs(this).getFloat("speed",.85f)*100)-50,100,50,"%",x->Store.prefs(this).edit().putFloat("speed",(x+50)/100f).apply());toggle("Автоматично наступний урок","auto",true);toggle("Повторювати поточний урок","repeat",false);add(body,label("Мови озвучування",15,ACCENT,true),25);add(body,label("Вибрана мова → українська → повтор вибраною мовою. Використовуються окремі мовні пакети Android.",15,MUTED,false),8);add(body,btn("Налаштування голосів Android",15,false,()->{try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(Exception e){startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}}),14);}
 interface Changed{void value(int v);}void slider(String title,int v,int max,int offset,String unit,Changed cb){TextView text=label(title+"   "+(v+offset)+unit,16,INK,true);add(body,text,20);SeekBar s=new SeekBar(this);s.setMax(max);s.setProgress(v);s.setProgressTintList(android.content.res.ColorStateList.valueOf(ACCENT));s.setThumbTintList(android.content.res.ColorStateList.valueOf(ACCENT));add(body,s,3);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean u){text.setText(title+"   "+(p+offset)+unit);if(u)cb.value(p);}});}
 void toggle(String title,String key,boolean def){Switch s=new Switch(this);s.setText(title);s.setTextColor(INK);s.setTextSize(15);s.setChecked(Store.prefs(this).getBoolean(key,def));s.setOnCheckedChangeListener((b,v)->Store.prefs(this).edit().putBoolean(key,v).apply());add(body,s,17);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==15&&result==RESULT_OK&&data!=null&&data.getData()!=null){try{String name="Новий урок";try(Cursor c=getContentResolver().query(data.getData(),null,null,null,null)){if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0)name=c.getString(i).replaceFirst("\\.[^.]+$","");}}importDialog(name,Store.read(getContentResolver().openInputStream(data.getData())));}catch(Exception e){new AlertDialog.Builder(this).setMessage("Не вдалося імпортувати: "+e.getMessage()).setPositiveButton("OK",null).show();}}}

 void importDialog(String title,String raw){if(importing){Toast.makeText(this,"Зачекай завершення імпорту",Toast.LENGTH_SHORT).show();return;}LinearLayout layout=column();layout.setPadding(dp(20),dp(8),dp(20),dp(12));EditText name=new EditText(this);name.setSingleLine(true);name.setHint("Назва уроку");name.setText(title);add(layout,name,0);Spinner langs=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Store.NAMES);langs.setAdapter(adapter);for(int i=0;i<Store.LANGS.length;i++)if(Store.LANGS[i].equals(filter))langs.setSelection(i);add(layout,label("Мова для вивчення",14,INK,true),12);add(layout,langs,0);CheckBox auto=new CheckBox(this);auto.setText("Автоматичний переклад з української");auto.setChecked(raw.isEmpty()||!raw.matches("(?s).*[|;\t].*"));add(layout,auto,10);EditText text=new EditText(this);text.setHint("Одна українська фраза на рядок");text.setText(raw);text.setGravity(Gravity.TOP);text.setMinLines(4);text.setMaxLines(8);add(layout,text,8);add(layout,label("Для автоматичного перекладу перше завантаження мовних моделей потребує інтернету. Якщо переклад уже є — зніми прапорець і використовуй формат фраза | переклад.",12,MUTED,false),8);ScrollView scroll=new ScrollView(this);scroll.addView(layout);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Новий урок").setView(scroll).setNegativeButton("Скасувати",null).setPositiveButton("Зберегти",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{String n=name.getText().toString().trim(),r=text.getText().toString().trim(),lang=Store.LANGS[langs.getSelectedItemPosition()];if(n.isEmpty()||r.isEmpty()){Toast.makeText(this,"Введи назву й фрази",0).show();return;}if(auto.isChecked()){ArrayList<String> lines=new ArrayList<>();for(String line:r.split("\\R")){line=line.trim();if(line.isEmpty())continue;if(!Store.cyr(line)||line.length()>1000||line.contains("|")){text.setError("Потрібні українські фрази без перекладу, до 1000 символів");return;}lines.add(line);}if(lines.isEmpty()||lines.size()>300){text.setError("Від 1 до 300 фраз за раз");return;}dialog.dismiss();translateLesson(n,lang,lines);}else try{int count=Store.add(this,n,r,lang);dialog.dismiss();filter=lang;show(1);Toast.makeText(this,"Додано фраз: "+count,Toast.LENGTH_LONG).show();}catch(Exception e){text.setError(e.getMessage());}}));dialog.show();}
 Translator translator; AlertDialog translationProgress; boolean cancelled=false;
 void translateLesson(String title,String lang,ArrayList<String> lines){importing=true;cancelled=false;translator=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage(TranslateLanguage.UKRAINIAN).setTargetLanguage(lang).build());translationProgress=new AlertDialog.Builder(this).setTitle("Переклад уроку").setMessage("Завантаження мовної моделі…").setCancelable(false).setNegativeButton("Скасувати",(d,k)->cancelTranslation()).create();translationProgress.show();Translator t=translator;t.downloadModelIfNeeded(new DownloadConditions.Builder().build()).addOnSuccessListener(v->{if(translator==t&&!cancelled)translateNext(t,title,lang,lines,0,new JSONArray());}).addOnFailureListener(e->{if(translator==t)translationError(e);});}
 void translateNext(Translator t,String title,String lang,ArrayList<String> lines,int index,JSONArray pairs){if(cancelled||translator!=t||isFinishing()||isDestroyed())return;if(index==lines.size()){try{Store.saveTranslated(this,title,lang,pairs);cancelTranslation();filter=lang;show(1);Toast.makeText(this,"Додано фраз: "+pairs.length(),Toast.LENGTH_LONG).show();}catch(Exception e){translationError(e);}return;}translationProgress.setMessage("Переклад фрази "+(index+1)+" з "+lines.size());String uk=lines.get(index);t.translate(uk).addOnSuccessListener(result->{if(translator!=t||cancelled)return;try{if(result.trim().isEmpty())throw new JSONException("Порожній переклад");pairs.put(new JSONObject().put("uk",uk).put("de",result));translateNext(t,title,lang,lines,index+1,pairs);}catch(Exception e){translationError(e);}}).addOnFailureListener(e->{if(translator==t)translationError(e);});}
 void cancelTranslation(){cancelled=true;importing=false;Translator t=translator;translator=null;if(t!=null)t.close();if(translationProgress!=null){translationProgress.dismiss();translationProgress=null;}}
 void translationError(Exception e){cancelTranslation();if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("Переклад не завершено").setMessage("Перевір інтернет і вільне місце. Урок не збережено. "+e.getMessage()).setPositiveButton("OK",null).show();}
 @Override protected void onDestroy(){cancelTranslation();super.onDestroy();}
